        fragmentShader: "\nprecision highp float;\n\nvarying vec2 vUv;\nvarying vec3 vViewNormal;\n\nconst float SKETCH_SCALE = 0.1;\n\nconst float HATCH_THICKNESS = 0.001;\nconst float HATCH_SMOOTHNESS = 0.025;\nconst float HATCH_WOBBLE = 1.0;\nconst float HATCH_INK_VARIATION = 0.9;\n\nconst float SHADOW_MIN_BRIGHTNESS = 0.88;\nconst float SHADOW_MAX_BRIGHTNESS = 1.0;\n\nconst vec3 PAPER_COLOR = vec3(0.91, 0.875, 0.81);\nconst vec3 INK_COLOR = vec3(0.25, 0.25, 0.25);\n\nconst vec2 FIRST_HATCH_DIRECTION = normalize(vec2(0.9, 0.45));\nconst vec2 SECOND_HATCH_DIRECTION = normalize(vec2(-0.15, 0.95));\n\nfloat hash(vec2 position) {\n\treturn fract(sin(dot(position, vec2(127.1, 311.7))) * 43758.5453123);\n}\n\nfloat noise(vec2 position) {\n\tvec2 cell = floor(position);\n\tvec2 local = fract(position);\n\tlocal *= local * (3.0 - 2.0 * local);\n\treturn mix(\n\t\tmix(hash(cell), hash(cell + vec2(1.0, 0.0)), local.x),\n\t\tmix(hash(cell + vec2(0.0, 1.0)), hash(cell + vec2(1.0, 1.0)), local.x),\n\t\tlocal.y\n\t);\n}\n\nfloat getPaperVariation(vec2 position) {\n\treturn mix(noise(position * 0.008), noise(position * 0.035), 0.2);\n}\n\nfloat getHatchVariation(vec2 position, vec2 direction) {\n\tfloat variation = mix(\n\t\tnoise(position * 0.018 + direction * 13.7),\n\t\tnoise(position * 0.065 + direction * 31.4),\n\t\t0.25\n\t);\n\treturn mix(1.0 - HATCH_INK_VARIATION, 1.0, smoothstep(0.15, 0.85, variation));\n}\n\nfloat hatch(vec2 position, vec2 direction) {\n\tvec2 grid = position * SKETCH_SCALE;\n\tfloat coordinate = dot(grid, direction);\n\tcoordinate += (noise(vec2(coordinate * 1.7, 0.0)) - 0.5) * HATCH_WOBBLE;\n\tfloat line = abs(fract(coordinate) - 0.5);\n\tfloat width = max(fwidth(coordinate), 0.001);\n\tfloat hatchLine = 1.0 - smoothstep(HATCH_THICKNESS, HATCH_THICKNESS + max(HATCH_SMOOTHNESS, width), line);\n\treturn hatchLine * getHatchVariation(position, direction);\n}\n\nfloat getHatch(vec2 position, float diffuse) {\n\tfloat first = hatch(position, FIRST_HATCH_DIRECTION) * (1.0 - smoothstep(0.32, 0.68, diffuse));\n\tfloat second = hatch(position, SECOND_HATCH_DIRECTION) * (1.0 - smoothstep(0.0, 0.38, diffuse));\n\treturn max(first, second);\n}\n\nvoid main() {\n\tif (vUv.y < 0.0) {\n\t\tgl_FragColor = vec4(INK_COLOR, 1.0);\n\t\treturn;\n\t}\n\tvec3 normal = normalize(vViewNormal);\n\tvec3 lightDirection = normalize(vec3(-0.5, 1.0, 0.5));\n\tfloat diffuse = max(dot(normal, lightDirection), 0.0);\n\tvec2 screenPosition = gl_FragCoord.xy;\n\tfloat paperBrightness = mix(0.97, 1.03, getPaperVariation(screenPosition));\n\tvec3 color = PAPER_COLOR * paperBrightness;\n\tcolor *= mix(SHADOW_MIN_BRIGHTNESS, SHADOW_MAX_BRIGHTNESS, diffuse);\n\tcolor = mix(color, INK_COLOR, getHatch(screenPosition, diffuse));\n\tgl_FragColor = vec4(color, 1.0);\n}\n"
